+uint64_t get_alloc_granularity() {
+  static uint64_t const granularity = [] {
+    ::SYSTEM_INFO info;
+    ::GetSystemInfo(&info);
+    return info.dwAllocationGranularity;
+  }();
+  return granularity;
+}
